"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["28029"],{61168(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>c,contentTitle:()=>p,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate","title":"Validate ABHA policy link (v2)","description":"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate","permalink":"/docs/pr-12/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Validate ABHA policy link (v2)","sidebar_label":"Validate ABHA policy link (v2)","sidebar_class_name":"api-method api-method--get","description":"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Initiate ABHA policy link (v2)","permalink":"/docs/pr-12/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-init"},"next":{"title":"De-link ABHA policies","permalink":"/docs/pr-12/docs/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy"}}'),n=a(62540),r=a(43023),s=a(44136),o=JSON.parse('{"id":"registry_v2_participant_link_abha_policy_validate","module":"Participant registry","moduleId":"registry","kind":"operation","method":"GET","path":"/v2/participant/link/abha/policy/validate","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Validate ABHA policy link (v2)","description":"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.\\n\\n### Business purpose\\n\\nThis GET endpoint closes the approval loop opened by /v2/participant/link/abha/policy/init. By requiring a passcode tied to a transactionId, it ensures that a member-layer write attributed to a payer or TPA was actually authorised by that organisation, in the same way that participant creation and update are confirmed through /validate and /update/validate. The value to the ecosystem is trust in the registry: providers rely on the policy lookup, so the links behind it should be deliberate and traceable.\\n\\n### When to use\\n\\nCall it after a successful init call, once the passcode is available, passing both required query parameters: passcode (string) and transactionId (string). It is the last step of the confirmed link flow and must be completed before the link is relied on. It has no role in claim-side workflows (eligibility, preauthorisation, claim) beyond making the member discoverable so that those flows can start.\\n\\n### Preconditions\\n\\n- A prior POST /v2/participant/link/abha/policy/init that returned a transaction identifier.\\n- The passcode associated with that transaction; the documentation for the sibling participant flows says the passcode is specific to each transaction id and valid for 24 hours.\\n- A valid Bearer token in bearer_auth: Bearer <token>, plus Accept: application/json; there is no request body, and no JWE or x-hcx-* headers are involved.\\n- The participant service base path, sandbox https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice.\\n\\n### Postconditions\\n\\nOn success the endpoint returns HTTP 200 with ParticipantLinkAbhaResponse (optional result and errormessage). The initiated link is confirmed and the beneficiary\'s products become discoverable through the policy lookup endpoints. No asynchronous callback follows. Errors return 400, 404 or 500 with the ErrorResponse envelope. If the transaction cannot be found or the passcode is wrong, the documented remedy for the sibling participant flows is to trigger the init request again, which generates a new transaction id and passcode.\\n\\n### Common mistakes\\n\\n- Sending passcode and transactionId in a JSON body instead of as query parameters; this is a GET with two required query parameters.\\n- Using a transactionId from a different init call or from a participant create/update flow.\\n- Letting the passcode age out; the sibling flows document a 24-hour validity for transaction id and passcode.\\n- Calling with a token from a client_id other than the one used at participant creation, which fails the link authorisation check.\\n- Omitting the Accept header or the Bearer prefix on bearer_auth.\\n\\n### Best practices\\n\\n- URL-encode both query parameters and log the transactionId with the outcome.\\n- Treat a 404 or an errormessage as a signal to restart from init rather than retrying the same passcode indefinitely.\\n- Verify the confirmed link with /participant/get/policies using the same ABHA number.\\n- Keep the init and validate calls under the same participant token so the identity check passes.\\n\\n### Related scenario\\n\\nA TPA\'s operations desk initiated a policy link for a new member earlier in the day through /v2/participant/link/abha/policy/init and stored the transaction identifier against the case. When the authorised approver supplies the passcode, the system calls GET /v2/participant/link/abha/policy/validate?passcode=...&transactionId=... and receives a 200 with a result string. The desk then runs /V2/participant/get/policies for the member\'s ABHA number, sees the product listed, and closes the linking task; the next call in the member\'s journey will be the hospital\'s coverage-eligibility check.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[],"responses":[{"status":"200","description":"On success the endpoint returns HTTP 200 with ParticipantLinkAbhaResponse (optional result and errormessage).","example":{"result":"success"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/validate\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Validate ABHA policy link (v2)",sidebar_label:"Validate ABHA policy link (v2)",sidebar_class_name:"api-method api-method--get",description:"Second half of the two-step v2 link: confirms an initiated ABHA policy link with the passcode and transactionId query parameters.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},p,d={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);